static void mochPeso(LinkedList<Objeto>L1,
                     LinkedList<Objeto>L2,
                     int max,int a,int b,int i){

    if(peso(L1)>max)return;

    if(!L1.isEmpty())
        System.out.println(L1);

    for(int k=i;k<L2.size();k++){

        Objeto x=L2.get(k);

        if(x.peso>=a && x.peso<=b){
            L1.add(x);
            mochPeso(L1,L2,max,a,b,k+1);
            L1.removeLast();
        }
    }
}
